/**
 * Offline accuracy eval of the rule parser on the synthetic capture set.
 *
 * Inputs (committed): tests/fixtures/screenshot_import/synthetic/
 *   *.png              — 12 synthetic broker screens (no real account data)
 *   ground_truth.json  — what a person reads on each screen
 *   ocr/*.png.json     — Tesseract.js output for each image, regenerated by
 *                        `node scripts/ocr-eval-dump.mjs <dir> <dir>/ocr`
 *
 * Per field we count: auto (filled and right), unknown (left blank for the
 * user), wrong (filled and wrong). The design goal is wrong ≈ 0; the test
 * fails if any field is filled wrongly or a non-fill screen yields rows.
 * `OCR_EVAL_PRINT=1 npx vitest run src/lib/fill-ocr` prints the table.
 */
import fs from "node:fs";
import path from "node:path";
import { describe, it, expect } from "vitest";
import { parseFillScreen, type OcrWord, type ParsedFill } from "@/lib/fill-ocr/parse";

const DIR = path.resolve(__dirname, "../../../../../tests/fixtures/screenshot_import/synthetic");

interface GtTrade {
  date: string; time: string | null; name: string; ticker: string | null;
  side: "buy" | "sell"; quantity: number; price: number; amount: number; currency: string;
}
interface GtScreen { screen_type: string; trades?: GtTrade[] }

const FIELDS = ["date", "time", "name", "side", "shares", "price", "amount", "currency"] as const;
type Field = (typeof FIELDS)[number];
type Tally = Record<Field, { auto: number; unknown: number; wrong: number; total: number }>;

function fieldValue(f: ParsedFill, k: Field): unknown {
  switch (k) {
    case "currency": return f.currency;
    case "name": return resolvedStock(f);
    default: return (f[k] as { value: unknown }).value;
  }
}

function truth(t: GtTrade, k: Field): unknown {
  switch (k) {
    case "shares": return t.quantity;
    case "side": return t.side === "buy" ? "BUY" : "SELL";
    case "name": return t.ticker ?? t.name;
    default: return (t as unknown as Record<string, unknown>)[k];
  }
}

// The server auto-accepts a stock only by a printed code or an EXACT master
// name; anything else is fuzzy-matched and marked for the user's check
// (routes/imports.py::resolve_ticker). The eval models that with the same
// master list (generated from services/kr_stock_registry).
const KR_NAMES = JSON.parse(
  fs.readFileSync(path.resolve(DIR, "../kr_names.json"), "utf8"),
) as Record<string, string>;

/** The stock the server would settle on without asking, or null. */
function resolvedStock(f: ParsedFill): string | null {
  if (f.code.value) return f.code.value.toUpperCase();
  const n = (f.name.value ?? "").replace(/\s+/g, "");
  return KR_NAMES[n] ?? null;
}

function equal(k: Field, got: unknown, want: unknown, f: ParsedFill, t: GtTrade): boolean {
  if (k === "name") {
    const wantCode = t.ticker ?? KR_NAMES[t.name.replace(/\s+/g, "")] ?? t.name;
    return resolvedStock(f) === wantCode.toUpperCase();
  }
  if (k === "time") return String(got).slice(0, 5) === String(want ?? "").slice(0, 5);
  return got === want;
}

function score(f: ParsedFill, t: GtTrade): number {
  let s = 0;
  for (const k of ["shares", "price", "amount"] as const) if (fieldValue(f, k) === truth(t, k)) s += 3;
  if (f.date.value === t.date) s += 1;
  if (f.time.value && t.time && f.time.value.slice(0, 5) === t.time.slice(0, 5)) s += 3;
  if (equal("name", null, null, f, t)) s += 2;
  const hints = [f.shares.hint, f.price.hint, f.amount.hint].join(" ").replace(/[^\d]/g, " ");
  for (const v of [t.quantity, t.price, t.amount]) if (hints.includes(String(v).replace(".", ""))) s += 1;
  return s;
}

function evaluate() {
  const gt = JSON.parse(fs.readFileSync(path.join(DIR, "ground_truth.json"), "utf8")) as Record<string, GtScreen>;
  const tally = Object.fromEntries(FIELDS.map((k) => [k, { auto: 0, unknown: 0, wrong: 0, total: 0 }])) as Tally;
  const screens: { file: string; want: string; got: string; rows: number; gtRows: number; extra: number }[] = [];
  const wrongs: string[] = [];
  for (const [file, g] of Object.entries(gt)) {
    const dump = JSON.parse(fs.readFileSync(path.join(DIR, "ocr", `${file}.json`), "utf8")) as
      OcrWord[] | { error: string };
    // A rejected input (e.g. below the minimum resolution) yields no rows —
    // every field of that screen counts as "left to the user".
    const rejected = !Array.isArray(dump);
    const res = rejected
      ? { screenType: `rejected:${dump.error}`, rows: [] as ParsedFill[], excluded: [] }
      : parseFillScreen(dump);
    const trades = g.trades ?? [];
    const used = new Set<number>();
    let extra = 0;
    const matchOf = new Map<number, ParsedFill>();
    for (const f of res.rows) {
      let best = -1, bestS = 0;
      trades.forEach((t, i) => {
        if (used.has(i)) return;
        const s = score(f, t);
        if (s > bestS) { best = i; bestS = s; }
      });
      if (best >= 0 && bestS >= 1) { used.add(best); matchOf.set(best, f); }
      else {
        extra += 1;
        // An invented row is wrong for every field it filled.
        for (const k of FIELDS) if (fieldValue(f, k) != null && k !== "currency") {
          tally[k].wrong += 1;
          wrongs.push(`${file} extra row ${k}=${String(fieldValue(f, k))}`);
        }
      }
    }
    trades.forEach((t, i) => {
      const f = matchOf.get(i);
      for (const k of FIELDS) {
        if (k === "time" && !t.time) continue;
        tally[k].total += 1;
        const got = f ? fieldValue(f, k) : null;
        if (got == null) tally[k].unknown += 1;
        else if (k === "time" && f?.tz === "ET") tally[k].unknown += 1; // ET time is not sent
        else if (equal(k, got, truth(t, k), f!, t)) tally[k].auto += 1;
        else { tally[k].wrong += 1; wrongs.push(`${file} #${i} ${k}: got ${String(got)} want ${String(truth(t, k))}`); }
      }
    });
    const want = g.screen_type === "order" ? "orders" : g.screen_type;
    screens.push({ file, want, got: res.screenType, rows: res.rows.length, gtRows: trades.length, extra });
  }
  return { tally, screens, wrongs };
}

describe("fill-screen OCR eval (synthetic set)", () => {
  const { tally, screens, wrongs } = evaluate();

  if (process.env.OCR_EVAL_PRINT) {
    const pct = (n: number, d: number) => (d ? `${Math.round((n / d) * 100)}%` : "-");
    const lines = ["| 칸 | 자동 인식 | 판별불가(사용자 입력) | 틀리게 확신 | n |", "|---|---|---|---|---|"];
    for (const k of FIELDS) {
      const t = tally[k];
      lines.push(`| ${k} | ${pct(t.auto, t.total)} (${t.auto}) | ${pct(t.unknown, t.total)} (${t.unknown}) | ${t.wrong} | ${t.total} |`);
    }
    lines.push("", "| 화면 | 기대 | 판정 | 행(추출/정답) | 없는 행 |", "|---|---|---|---|---|");
    for (const s of screens) lines.push(`| ${s.file} | ${s.want} | ${s.got} | ${s.rows}/${s.gtRows} | ${s.extra} |`);
    console.log(lines.join("\n"));
    if (wrongs.length) console.log("WRONG:\n" + wrongs.join("\n"));
  }

  it("classifies every screen (or rejects the input before reading)", () => {
    for (const s of screens) {
      if (s.got.startsWith("rejected:")) continue;
      expect(`${s.file}:${s.got}`).toBe(`${s.file}:${s.want}`);
    }
  });

  it("never fills a cell wrongly", () => {
    expect(wrongs).toEqual([]);
  });

  it("non-fill screens yield no rows", () => {
    for (const s of screens.filter((x) => x.want !== "fills")) expect(s.rows).toBe(0);
  });
});
